CREATE TABLE dispatch_commission_assets(id UUID PRIMARY KEY,center_id BIGINT REFERENCES records(id),name TEXT NOT NULL,mime_type TEXT NOT NULL,content BYTEA NOT NULL CHECK(octet_length(content)>0 AND octet_length(content)<=2097152),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE dispatch_commission_accounts(center_id BIGINT PRIMARY KEY REFERENCES records(id),balance NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK(balance>=0),reserved NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=balance));
CREATE TABLE dispatch_payout_settings(id INTEGER PRIMARY KEY CHECK(id=1),data JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1);
INSERT INTO dispatch_payout_settings(id,data) VALUES(1,'{"methods":[{"id":"bank","name":"Bank Transfer","kind":"Bank","active":true},{"id":"esewa","name":"eSewa","kind":"Wallet","active":true},{"id":"cash","name":"Cash","kind":"Cash","active":true}]}');
CREATE TABLE dispatch_payout_profiles(center_id BIGINT PRIMARY KEY REFERENCES records(id),data JSONB NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE dispatch_commission_withdrawals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,center_id BIGINT NOT NULL REFERENCES records(id),amount NUMERIC(18,2) NOT NULL CHECK(amount>0),status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Paid','Rejected','Cancelled')),request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,payout_snapshot JSONB NOT NULL,remarks TEXT NOT NULL DEFAULT '',admin_remarks TEXT NOT NULL DEFAULT '',payment_reference TEXT NOT NULL DEFAULT '',payment_proof_id UUID REFERENCES dispatch_commission_assets(id),requested_by TEXT NOT NULL,reviewed_by TEXT,paid_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1,UNIQUE(center_id,request_key));
CREATE TABLE dispatch_commission_ledger(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,center_id BIGINT NOT NULL REFERENCES records(id),amount NUMERIC(18,2) NOT NULL CHECK(amount<>0),balance_after NUMERIC(18,2) NOT NULL CHECK(balance_after>=0),reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,dispatch_id BIGINT REFERENCES inventory_dispatches(id),product_id BIGINT REFERENCES records(id),withdrawal_id BIGINT REFERENCES dispatch_commission_withdrawals(id),details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX dispatch_commission_ledger_center ON dispatch_commission_ledger(center_id,id DESC);
CREATE INDEX dispatch_commission_withdrawals_center ON dispatch_commission_withdrawals(center_id,status,id DESC);
CREATE TRIGGER dispatch_commission_immutable BEFORE UPDATE OR DELETE ON dispatch_commission_ledger FOR EACH ROW EXECUTE FUNCTION protect_member_ledger();
